#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Enemies
{
    [AutoBuffDefinition(VanillaBuffNames.Enemy.ridingPassenger)]
    public class RidingPassengerBuff : BuffDefinition
    {
        public RidingPassengerBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicEnemyProps.HARMLESS, true));
            AddModifier(new BooleanModifier(LogicEnemyProps.FORCED_MOVEMENT, true));
            AddModifier(new EntityIDModifier(LogicEnemyProps.FOLLOWED_KILLER_TARGET, SetOperator.SetIfNotNull, PROP_TARGET));
            AddModifier(new Vector3Modifier(LogicEnemyProps.POSITION_OFFSET_RELATIVE_TO_KILLER, NumberOperator.Set, PROP_POSITION_OFFSET));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            var riding = GetRidingEntity(buff);
            if (!riding.ExistsAndAlive() || riding.IsHostile(entity))
            {
                entity.GetOffPassenger();
            }
            else
            {
                entity.UpdatePassengerPosition(riding);
                buff.SetProperty(PROP_POSITION_OFFSET, riding.GetPassengerOffset());
                entity.Velocity = Vector3.zero;
                entity.StopMonsterMotionBuffs();
            }
        }
        public static Entity? GetRidingEntity(Buff buff)
        {
            var entityID = buff.GetProperty<EntityID>(PROP_TARGET);
            return entityID?.GetEntity(buff.Level);
        }
        public static void SetRidingEntity(Buff buff, Entity value)
        {
            buff.SetProperty(PROP_TARGET, new EntityID(value));
        }
        public static readonly PropertyMeta<Vector3> PROP_POSITION_OFFSET = new PropertyMeta<Vector3>("position_offset");
        public static readonly PropertyMeta<EntityID> PROP_TARGET = new PropertyMeta<EntityID>("Target");
    }
}
